package ai.eva.android.probe;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;
/** Isolated package only: API form, capability preservation and DSH scope. No upstream traffic. */
public final class ModelSettingsPolicyCheck extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}
 static void check(boolean v,String reason){if(!v)throw new AssertionError(reason);}
 static String labels(View v){StringBuilder out=new StringBuilder();if(v.isShown()&&v instanceof TextView)out.append(((TextView)v).getText()).append('\n');if(v instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)v;for(int i=0;i<group.getChildCount();i++)out.append(labels(group.getChildAt(i)));}return out.toString();}
 public void onStart(){Bundle out=new Bundle();ModelStore store=new ModelStore(getTargetContext());String prior=store.prefs().getString("config",null);ModelsActivity a=null;try{
  String deep=store.save("","My DeepSeek","https://api.deepseek.com","deepseek-flash","fixture-key","responses");store.setDefaultSelection(deep,"deepseek-flash","max","");String defaults=store.read().getJSONObject("defaultSelection").toString();
  String dsh=store.save("","本机免费模型",DshAvailability.URL,"bad","fixture-key","chat_completions");store.cacheModels(dsh,new JSONArray("[{id:'good',reasoningEfforts:['low','high']},{id:'bad'}]"));JSONObject expected=store.provider(dsh);String stamp=store.runtimeStamp();store.dshResult(dsh,expected,"good",true,System.currentTimeMillis(),"fixture passed");store.dshResult(dsh,expected,"bad",false,System.currentTimeMillis(),"fixture failed");check(store.runtimeStamp().equals(stamp),"health updates restarted connection identity");
  JSONObject pub=store.publicConfig();for(int i=0;i<pub.getJSONArray("providers").length();i++){JSONObject p=pub.getJSONArray("providers").getJSONObject(i);if(p.getString("id").equals(deep))check(p.getJSONArray("models").getJSONObject(0).getJSONArray("reasoningEfforts").toString().contains("max"),"manual DeepSeek effort missing");if(p.getString("id").equals(dsh))check(p.getString("name").equals("DSH插件")&&p.getJSONArray("models").length()==1,"DSH filter");}
  check(store.read().getJSONObject("defaultSelection").toString().equals(defaults),"health changed default");boolean rejected=false;try{store.setDefaultSelection(dsh,"bad","","");}catch(java.io.IOException expectedFailure){rejected=true;}check(rejected,"unavailable DSH selected as default");
  a=(ModelsActivity)startActivitySync(new Intent(getTargetContext(),ModelsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final ModelsActivity ui=a;runOnMainSync(()->{check(ui.name!=null&&ui.url!=null&&ui.apiKey!=null&&ui.model!=null,"entry does not directly expose four fields");String text=labels(ui.getWindow().getDecorView());check(text.contains("供应商名称")&&text.contains("URL")&&text.contains("API Key")&&text.contains("模型名称"),"four labels");check(!text.contains("接入")&&!text.contains("本机免费")&&!text.contains("DSH插件")&&!text.contains("Responses"),"unrelated plugin/protocol on plain API form");ui.name.setText("New API");ui.url.setText("https://fixture.invalid/v1");ui.apiKey.setText("fixture-new-key");ui.model.setText("fixture-model");check(ui.save(),"four-field save failed");check(ui.save(),"repeat save failed");});
  check(store.provider(ui.editing).getString("protocol").equals("chat_completions"),"new API default protocol");check(store.read().getJSONObject("defaultSelection").toString().equals(defaults),"saving API changed default");check(ModelsActivity.automaticProtocol("https://api.deepseek.com").equals("responses"),"official DeepSeek protocol");out.putString("result","PASS direct four-field API form, save/readback, unrelated entries absent, DeepSeek efforts, DSH filtering/default guard and identity/default preservation");finish(-1,out);
 }catch(Throwable e){out.putString("error",e.toString());finish(0,out);}finally{if(prior==null)store.prefs().edit().remove("config").commit();else store.prefs().edit().putString("config",prior).commit();}}
}
